"use strict";const e=require("../common/vendor.js"),n=e.createStore({state:{token:e.index.getStorageSync("session_token")||"",userInfo:e.index.getStorageSync("user_info")||null},mutations:{SET_TOKEN(n,o){n.token=o,e.index.setStorageSync("session_token",o)},SET_USER(n,o){n.userInfo=o,e.index.setStorageSync("user_info",o)},LOGOUT(n){n.token="",n.userInfo=null,e.index.removeStorageSync("session_token"),e.index.removeStorageSync("user_info")}},getters:{isLogin:e=>!!e.token}});exports.store=n;
